INSERT INTO ops.demo_checks (run_at, demo, ok, wake_ms, page_ms, status_code, problem, details, source)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8::jsonb, $9)
ON CONFLICT (run_at, demo) DO NOTHING;

