// Build the Telegram report from this run plus 7-day stats.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const run = $('Validate & flatten').all().map((i) => i.json);
const stats = Object.fromEntries(
  $input.all().filter((i) => i.json.demo).map((i) => [i.json.demo, i.json])
);

const down = run.filter((d) => !d.ok);
const when = DateTime.fromISO(run[0].run_at).setZone('Asia/Dubai').toFormat('dd LLL, HH:mm');

const lines = run
  .sort((a, b) => a.demo.localeCompare(b.demo))
  .map((d) => {
    const s = stats[d.demo];
    const week = s ? ` · 7d ${s.uptime_pct}%` : '';
    if (d.ok) {
      const wake = d.wake_ms != null ? `woke in ${(d.wake_ms / 1000).toFixed(1)}s` : 'up';
      return `✅ <b>${esc(d.demo)}</b>: ${wake}${week}`;
    }
    const why = d.problem ? `\n     ${esc(d.problem)}` : '';
    return `❌ <b>${esc(d.demo)}</b>: DOWN${week}${why}`;
  });

const header = down.length
  ? `🚨 <b>Demo check: ${down.length} of ${run.length} down</b>`
  : `🟢 <b>Demo check: all ${run.length} up</b>`;

return [{
  json: {
    text: `${header}\n<i>${when} (Dubai)</i>\n\n${lines.join('\n')}`,
    silent: down.length === 0,
  },
}];

